function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function fetchJson(path,options={}){const response=await fetch(origin()+path,{headers:{Accept:'application/json','Content-Type':'application/json'},...options});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.json()}
async function invoke(name,input){const payload=await fetchJson('/api/agent/data-tools/'+name+'/invoke',{method:'POST',body:JSON.stringify({input})});return payload.result}
function boundedRows(rows,limit){const count=rows.length;if(count<=limit)return{rows,row_count:count,rows_truncated:false};const head=Math.ceil(limit/2),tail=Math.floor(limit/2);return{rows:[...rows.slice(0,head),...rows.slice(count-tail)],row_count:count,rows_truncated:true}}
function compactRows(payload,limit){if(Array.isArray(payload))return boundedRows(payload,limit);if(!payload||typeof payload!=='object')return payload;for(const key of ['rows','items','values','series']){if(Array.isArray(payload[key])){const sampled=boundedRows(payload[key],limit);return{...payload,[key]:sampled.rows,[key+'_count']:sampled.row_count,[key+'_truncated']:sampled.rows_truncated}}}return payload}
async function run(input){const action=String(input.action||''),limit=Math.max(1,Math.min(200,Number(input.limit||50)));if(action==='catalog')return invoke('data.catalog',{});if(action==='status')return invoke('data.status',{});if(action==='query'){if(!input.dataset)throw new Error('dataset is required for query');const body={dataset:input.dataset,limit};for(const key of ['symbols','start','end','columns'])if(input[key]!==undefined)body[key]=input[key];return compactRows(await invoke('data.query',body),limit)}if(action==='validate'){if(!input.dataset)throw new Error('dataset is required for validate');return invoke('data.validate',{dataset:input.dataset})}if(action==='market_bars'){const symbol=String(input.symbol||'').trim();if(!symbol)throw new Error('symbol is required for market_bars');const params=new URLSearchParams({symbol,profile:'runtime'});if(input.start)params.set('start',String(input.start));if(input.end)params.set('end',String(input.end));return compactRows(await fetchJson('/api/data/market/bars?'+params),limit)}if(action==='fundamentals'){if(!Array.isArray(input.symbols)||!input.symbols.length)throw new Error('symbols are required for fundamentals');const params=new URLSearchParams({profile:'runtime',limit:String(limit)});for(const symbol of input.symbols)params.append('symbols',String(symbol));for(const field of input.fields||[])params.append('fields',String(field));if(input.start_quarter)params.set('start_quarter',String(input.start_quarter));if(input.end_quarter)params.set('end_quarter',String(input.end_quarter));if(input.asof_date)params.set('asof_date',String(input.asof_date));return compactRows(await fetchJson('/api/data/fundamentals?'+params),limit)}if(action==='factor_returns'){const params=new URLSearchParams({profile:'runtime'});for(const name of input.names||[])params.append('names',String(name));if(input.start)params.set('start',String(input.start));if(input.end)params.set('end',String(input.end));return compactRows(await fetchJson('/api/data/factors/returns?'+params),limit)}throw new Error('unsupported data query action')}
